 public function __construct(private Repository $repo,private View $view,private Access $access,private Audit $audit){}
 public function stocks():void{$this->access->demand('inventory.view');$branch=(int)($_GET['branch_id']??0);$warehouse=(int)($_GET['warehouse_id']??0);$q=trim((string)($_GET['q']??''));if($branch)$this->access->demandBranch($branch);if($warehouse){$w=$this->repo->one('SELECT id,branch_id FROM inv_warehouses WHERE id=? AND active=1',[$warehouse]);if(!$w||($branch&&((int)$w['branch_id']!==$branch))||!$this->access->branch((int)($w['branch_id']??0)))throw new \Hls\Http\HttpError(404,'Gudang tidak ditemukan.');$branch=(int)$w['branch_id'];}$scope=$branch?' AND b.id=?':' AND b.id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1)';$args=$branch?[$branch]:[$this->access->user['id'],$this->access->user['all_branches']];$search='';if($q!==''){$search=' AND (i.code LIKE ? OR i.name LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}$warehouseSql=$warehouse?' AND w.id=?':' AND w.active=1';if($warehouse)$args[]=$warehouse;$rows=$this->repo->all('SELECT i.id,i.code,i.name,c.name category_name,u.name unit_name,b.id branch_id,b.code branch_code,b.name branch_name,w.id warehouse_id,w.code warehouse_code,w.name warehouse_name,COALESCE((SELECT SUM(l.quantity_change) FROM inv_stock_ledger l WHERE l.item_id=i.id AND l.branch_id=b.id AND l.warehouse_id=w.id),0) stock_qty FROM md_items i JOIN md_categories c ON c.id=i.category_id JOIN md_units u ON u.id=i.unit_id CROSS JOIN branches b JOIN inv_warehouses w ON w.branch_id=b.id WHERE i.active=1'.$scope.$warehouseSql.$search.' ORDER BY i.code,b.code,w.code',$args);$unallocated=$this->repo->all('SELECT i.id,i.code,i.name,c.name category_name,u.name unit_name,b.id branch_id,b.code branch_code,b.name branch_name,COALESCE((SELECT SUM(l.quantity_change) FROM inv_stock_ledger l WHERE l.item_id=i.id AND l.branch_id=b.id AND l.warehouse_id IS NULL),0) stock_qty FROM md_items i JOIN md_categories c ON c.id=i.category_id JOIN md_units u ON u.id=i.unit_id CROSS JOIN branches b WHERE i.active=1'.$scope.' AND EXISTS(SELECT 1 FROM inv_stock_ledger z WHERE z.item_id=i.id AND z.branch_id=b.id AND z.warehouse_id IS NULL)'.$search,$args);foreach($unallocated as &$urow){$urow['warehouse_id']=null;$urow['warehouse_code']=null;$urow['warehouse_name']='Belum dialokasikan';}$rows=array_merge($rows,$unallocated);$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1 ORDER BY code');$warehouses=$this->repo->all('SELECT id,branch_id,code,name FROM inv_warehouses WHERE active=1 ORDER BY code');$available=count(array_filter($rows,fn($r)=>(float)$r['stock_qty']>0));$this->view->render('inventory-stocks',['title'=>'Stok Barang','rows'=>$rows,'branches'=>$branches,'warehouses'=>$warehouses,'branch_id'=>$branch,'warehouse_id'=>$warehouse,'q'=>$q,'total_types'=>count(array_unique(array_column($rows,'id'))),'total_warehouses'=>count(array_unique(array_filter(array_column($rows,'warehouse_id')))),'available'=>$available]);}
 public function stockDetail():void{$this->access->demand('inventory.view');$item=Input::id($_GET,'item_id');$branch=Input::id($_GET,'branch_id');$warehouse=(int)($_GET['warehouse_id']??0);$this->access->demandBranch($branch);if($warehouse&&!$this->repo->one('SELECT id FROM inv_warehouses WHERE id=? AND branch_id=? AND active=1',[$warehouse,$branch]))throw new \Hls\Http\HttpError(404,'Gudang tidak ditemukan.');$page=max(1,(int)($_GET['page']??1));$limit=50;$offset=($page-1)*$limit;$where='item_id=? AND branch_id=? AND '.($warehouse?'warehouse_id=?':'warehouse_id IS NULL');$args=$warehouse?[$item,$branch,$warehouse]:[$item,$branch];$total=(int)$this->repo->one('SELECT COUNT(*) c FROM inv_stock_ledger WHERE '.$where,$args)['c'];$rows=$this->repo->all('SELECT l.*,CASE WHEN l.quantity_change>0 THEN l.quantity_change ELSE 0 END qty_in,CASE WHEN l.quantity_change<0 THEN -l.quantity_change ELSE 0 END qty_out FROM inv_stock_ledger l WHERE '.$where.' ORDER BY l.transaction_date,l.id LIMIT '.$limit.' OFFSET '.$offset,$args);$product=$this->repo->one('SELECT i.code,i.name,u.name unit_name FROM md_items i JOIN md_units u ON u.id=i.unit_id WHERE i.id=?',[$item]);$this->view->render('inventory-stock-detail',['title'=>'Stok Barang','product'=>$product,'rows'=>$rows,'branch_id'=>$branch,'warehouse_id'=>$warehouse,'page'=>$page,'pages'=>max(1,(int)ceil($total/$limit))]);} public function receipts():void{$this->access->demand('inventory.receipt.view');$where='';$args=[];$branch=(int)($_GET['branch_id']??0);if($branch){$this->access->demandBranch($branch);$where=' AND r.branch_id=?';$args[]=$branch;}else{$where=' AND r.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1)';$args=[$this->access->user['id'],$this->access->user['all_branches']];}$rows=$this->repo->all('SELECT r.*,b.code branch_code,s.name supplier_name,w.code warehouse_code,w.name warehouse_name,(SELECT COUNT(*) FROM inv_receipt_lines l WHERE l.receipt_id=r.id) line_count,(SELECT COALESCE(SUM(quantity),0) FROM inv_receipt_lines l WHERE l.receipt_id=r.id) total_qty FROM inv_receipts r JOIN branches b ON b.id=r.branch_id LEFT JOIN md_suppliers s ON s.id=r.supplier_id LEFT JOIN inv_warehouses w ON w.id=r.warehouse_id WHERE 1=1'.$where.' ORDER BY r.id DESC',$args);$items=$this->repo->all('SELECT id,code,name FROM md_items WHERE active=1 ORDER BY code');$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1 ORDER BY code');$suppliers=$this->repo->all('SELECT id,name,branch_id FROM md_suppliers WHERE active=1');$warehouses=$this->repo->all('SELECT id,branch_id,code,name FROM inv_warehouses WHERE active=1 ORDER BY code');$this->view->render('inventory-receipts',['title'=>'Barang Masuk','rows'=>$rows,'items'=>$items,'branches'=>$branches,'suppliers'=>$suppliers,'warehouses'=>$warehouses,'branch_id'=>$branch]);} public function receiptSave():void{$this->access->demand('inventory.receipt.create');$branch=Input::id($_POST,'branch_id');$this->access->demandBranch($branch);$warehouse=Input::id($_POST,'warehouse_id');$reservation=(int)($_POST['reservation_id']??0);if($reservation){$rr=$this->repo->one('SELECT * FROM inv_reservations WHERE id=? AND status="RESERVED"',[$reservation]);if(!$rr||((int)$rr['branch_id']!==$branch)||((int)$rr['warehouse_id']!==$warehouse))throw new \Hls\Http\HttpError(422,'Reservasi tidak valid untuk gudang ini.');}if(!$this->repo->one('SELECT id FROM inv_warehouses WHERE id=? AND branch_id=? AND active=1',[$warehouse,$branch]))throw new \Hls\Http\HttpError(422,'Gudang tujuan tidak aktif atau tidak sesuai cabang.');$date=Input::text($_POST,'receipt_date',10);$items=$_POST['item_id']??[];$qty=$_POST['quantity']??[];$ref=trim((string)($_POST['receipt_ref']??''));if(!is_array($items)||!is_array($qty)||$ref==='')throw new \Hls\Http\HttpError(422,'Data penerimaan tidak valid.');$lines=[];foreach($items as $i=>$item){$q=(float)($qty[$i]??0);if(!$item||$q<=0)continue;if(!$this->repo->one('SELECT id FROM md_items WHERE id=? AND active=1',[(int)$item]))throw new \Hls\Http\HttpError(422,'Barang tidak aktif.');$lines[]=[(int)$item,$q];}if(!$lines)throw new \Hls\Http\HttpError(422,'Minimal satu barang diperlukan.');$this->repo->db->beginTransaction();try{$this->repo->run('INSERT INTO inv_receipts(receipt_ref,receipt_date,branch_id,warehouse_id,supplier_id,document_ref,note,status,created_by,created_at) VALUES(?,?,?,?,?,?,?,"DRAFT",?,NOW())',[$ref,$date,$branch,$warehouse,($_POST['supplier_id']??'')?:null,trim((string)($_POST['document_ref']??''))?:null,trim((string)($_POST['note']??''))?:null,$this->access->user['id']]);$id=(int)$this->repo->db->lastInsertId();foreach($lines as $l)$this->repo->run('INSERT INTO inv_receipt_lines(receipt_id,item_id,quantity,unit_price,created_at) VALUES(?,?,?,?,NOW())',[$id,$l[0],$l[1],null]);$this->repo->db->commit();$this->view->redirect('/inventory/receipts');}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}} public function receiptDetail():void{$this->access->demand('inventory.receipt.view');$id=Input::id($_GET,'id');$row=$this->repo->one('SELECT r.*,b.code branch_code,s.name supplier_name,w.code warehouse_code,w.name warehouse_name FROM inv_receipts r JOIN branches b ON b.id=r.branch_id LEFT JOIN md_suppliers s ON s.id=r.supplier_id LEFT JOIN inv_warehouses w ON w.id=r.warehouse_id WHERE r.id=?',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new \Hls\Http\HttpError(404,'Transaksi tidak ditemukan.');$lines=$this->repo->all('SELECT l.*,i.code item_code,i.name item_name,u.name unit_name FROM inv_receipt_lines l JOIN md_items i ON i.id=l.item_id JOIN md_units u ON u.id=i.unit_id WHERE l.receipt_id=?',[$id]);$this->view->render('inventory-receipt-detail',['title'=>'Barang Masuk','row'=>$row,'lines'=>$lines]);} public function receiptPost():void{$this->access->demand('inventory.receipt.post');$id=Input::id($_POST,'id');$this->repo->db->beginTransaction();try{$row=$this->repo->one('SELECT * FROM inv_receipts WHERE id=? FOR UPDATE',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new \Hls\Http\HttpError(404,'Transaksi tidak ditemukan.');if($row['status']!=='DRAFT')throw new \Hls\Http\HttpError(409,'Transaksi sudah diposting.');if(empty($row['warehouse_id'])||!$this->repo->one('SELECT id FROM inv_warehouses WHERE id=? AND branch_id=? AND active=1',[$row['warehouse_id'],$row['branch_id']]))throw new \Hls\Http\HttpError(422,'Gudang tujuan tidak aktif.');$lines=$this->repo->all('SELECT * FROM inv_receipt_lines WHERE receipt_id=? FOR UPDATE',[$id]);if(!$lines)throw new \Hls\Http\HttpError(422,'Detail transaksi kosong.');foreach($lines as $l)$this->repo->run('INSERT INTO inv_stock_ledger(item_id,branch_id,warehouse_id,quantity_change,transaction_type,reference_type,reference_id,transaction_date,note,created_by,created_at) VALUES(?,?,?, ?,"RECEIPT","INV_RECEIPT",?,?,?, ?,NOW())',[$l['item_id'],$row['branch_id'],$row['warehouse_id'],$l['quantity'],$id,$row['receipt_date'],$row['note'],$this->access->user['id']]);$this->repo->run('UPDATE inv_receipts SET status="POSTED",posted_by=?,posted_at=NOW() WHERE id=? AND status="DRAFT"',[$this->access->user['id'],$id]);$this->repo->db->commit();$this->view->redirect('/inventory/receipt-detail?id='.$id);}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}} public function issues():void{$this->access->demand('inventory.issue.view');$where='';$args=[];$branch=(int)($_GET['branch_id']??0);if($branch){$this->access->demandBranch($branch);$where=' AND x.branch_id=?';$args[]=$branch;}else{$where=' AND x.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1)';$args=[$this->access->user['id'],$this->access->user['all_branches']];}$rows=$this->repo->all('SELECT x.*,b.code branch_code,w.code warehouse_code,w.name warehouse_name,(SELECT COUNT(*) FROM inv_issue_lines l WHERE l.issue_id=x.id) line_count,(SELECT COALESCE(SUM(quantity),0) FROM inv_issue_lines l WHERE l.issue_id=x.id) total_qty FROM inv_issues x JOIN branches b ON b.id=x.branch_id LEFT JOIN inv_warehouses w ON w.id=x.warehouse_id WHERE 1=1'.$where.' ORDER BY x.id DESC',$args);$items=$this->repo->all('SELECT i.id,i.code,i.name,COALESCE((SELECT SUM(l.quantity_change) FROM inv_stock_ledger l WHERE l.item_id=i.id AND l.branch_id=? AND l.warehouse_id=?),0) stock_qty FROM md_items i WHERE i.active=1 ORDER BY i.code',[$branch ?: 0,0]);$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1 ORDER BY code');$warehouses=$this->repo->all('SELECT id,branch_id,code,name FROM inv_warehouses WHERE active=1 ORDER BY code');$reservations=$this->repo->all('SELECT id,reservation_ref,branch_id,warehouse_id FROM inv_reservations WHERE status="RESERVED" AND branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY id DESC',[$this->access->user['id'],$this->access->user['all_branches']]);$this->view->render('inventory-issues',['title'=>'Barang Keluar','rows'=>$rows,'items'=>$items,'branches'=>$branches,'warehouses'=>$warehouses,'reservations'=>$reservations,'branch_id'=>$branch]);} public function issueSave():void{$this->access->demand('inventory.issue.create');$branch=Input::id($_POST,'branch_id');$this->access->demandBranch($branch);$warehouse=Input::id($_POST,'warehouse_id');$reservation=(int)($_POST['reservation_id']??0);if($reservation){$rr=$this->repo->one('SELECT * FROM inv_reservations WHERE id=? AND status="RESERVED"',[$reservation]);if(!$rr||((int)$rr['branch_id']!==$branch)||((int)$rr['warehouse_id']!==$warehouse))throw new \Hls\Http\HttpError(422,'Reservasi tidak valid untuk gudang ini.');}if(!$this->repo->one('SELECT id FROM inv_warehouses WHERE id=? AND branch_id=? AND active=1',[$warehouse,$branch]))throw new \Hls\Http\HttpError(422,'Gudang asal tidak aktif atau tidak sesuai cabang.');$date=Input::text($_POST,'issue_date',10);$ids=$_POST['item_id']??[];$qty=$_POST['quantity']??[];$ref=trim((string)($_POST['issue_ref']??''));if(!is_array($ids)||!is_array($qty)||$ref==='')throw new \Hls\Http\HttpError(422,'Data barang keluar tidak valid.');$lines=[];foreach($ids as $i=>$item){$q=(float)($qty[$i]??0);if(!$item||$q<=0)continue;if(!$this->repo->one('SELECT id FROM md_items WHERE id=? AND active=1',[(int)$item]))throw new \Hls\Http\HttpError(422,'Barang tidak aktif.');$lines[]=[(int)$item,$q];}if(!$lines)throw new \Hls\Http\HttpError(422,'Minimal satu barang diperlukan.');$this->repo->db->beginTransaction();try{$this->repo->run('INSERT INTO inv_issues(issue_ref,issue_date,branch_id,warehouse_id,reservation_id,recipient,document_ref,note,status,created_by,created_at) VALUES(?,?,?,?,?,?,?, ?,"DRAFT",?,NOW())',[$ref,$date,$branch,$warehouse,$reservation?:null,trim((string)($_POST['recipient']??''))?:null,trim((string)($_POST['document_ref']??''))?:null,trim((string)($_POST['note']??''))?:null,$this->access->user['id']]);$id=(int)$this->repo->db->lastInsertId();foreach($lines as $l)$this->repo->run('INSERT INTO inv_issue_lines(issue_id,item_id,quantity,created_at) VALUES(?,?,?,NOW())',[$id,$l[0],$l[1]]);$this->repo->db->commit();$this->view->redirect('/inventory/issues');}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}} public function issueDetail():void{$this->access->demand('inventory.issue.view');$id=Input::id($_GET,'id');$row=$this->repo->one('SELECT x.*,b.code branch_code,w.code warehouse_code,w.name warehouse_name FROM inv_issues x JOIN branches b ON b.id=x.branch_id LEFT JOIN inv_warehouses w ON w.id=x.warehouse_id WHERE x.id=?',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new \Hls\Http\HttpError(404,'Transaksi tidak ditemukan.');$lines=$this->repo->all('SELECT l.*,i.code item_code,i.name item_name,u.name unit_name FROM inv_issue_lines l JOIN md_items i ON i.id=l.item_id JOIN md_units u ON u.id=i.unit_id WHERE l.issue_id=?',[$id]);$this->view->render('inventory-issue-detail',['title'=>'Barang Keluar','row'=>$row,'lines'=>$lines]);} public function issuePost():void{$this->access->demand('inventory.issue.post');$id=Input::id($_POST,'id');$this->repo->db->beginTransaction();try{$row=$this->repo->one('SELECT * FROM inv_issues WHERE id=? FOR UPDATE',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new \Hls\Http\HttpError(404,'Transaksi tidak ditemukan.');if($row['status']!=='DRAFT')throw new \Hls\Http\HttpError(409,'Transaksi sudah diposting.');$lines=$this->repo->all('SELECT * FROM inv_issue_lines WHERE issue_id=? ORDER BY item_id FOR UPDATE',[$id]);$totals=[];foreach($lines as $l)$totals[(int)$l['item_id']]=($totals[(int)$l['item_id']]??0)+(float)$l['quantity'];$reservation=(int)($row['reservation_id']??0);if($reservation){$rr=$this->repo->one('SELECT * FROM inv_reservations WHERE id=? FOR UPDATE',[$reservation]);if(!$rr||$rr['status']!=='RESERVED')throw new \Hls\Http\HttpError(409,'Reservasi tidak valid.');}foreach($totals as $item=>$qty){$this->repo->one('SELECT id FROM md_items WHERE id=? FOR UPDATE',[$item]);$stock=(float)$this->repo->one('SELECT COALESCE(SUM(quantity_change),0) q FROM inv_stock_ledger WHERE item_id=? AND branch_id=? AND warehouse_id=?',[$item,$row['branch_id'],$row['warehouse_id']])['q'];if(!$reservation){$held=(float)$this->repo->one('SELECT COALESCE(SUM(rl.quantity_reserved-rl.quantity_fulfilled),0) q FROM inv_reservation_lines rl JOIN inv_reservations r ON r.id=rl.reservation_id WHERE r.status="RESERVED" AND r.branch_id=? AND r.warehouse_id=? AND rl.item_id=?',[$row['branch_id'],$row['warehouse_id'],$item])['q'];$stock-=$held;}if($stock<$qty)throw new \Hls\Http\HttpError(422,'Stok tersedia tidak mencukupi.');}$this->repo->run('INSERT INTO inv_stock_ledger(item_id,branch_id,warehouse_id,quantity_change,transaction_type,reference_type,reference_id,transaction_date,note,created_by,created_at) VALUES(?,?,?, ?,"ISSUE","INV_ISSUE",?,?,?, ?,NOW())',[$item,$row['branch_id'],$row['warehouse_id'],-$qty,$id,$row['issue_date'],$row['note'],$this->access->user['id']]);if($reservation){$this->repo->run('UPDATE inv_reservation_lines SET quantity_fulfilled=quantity_reserved WHERE reservation_id=?',[$reservation]);$this->repo->run('UPDATE inv_reservations SET status="FULFILLED",fulfilled_at=NOW() WHERE id=? AND status="RESERVED"',[$reservation]);}$this->repo->run('UPDATE inv_issues SET status="POSTED",posted_by=?,posted_at=NOW() WHERE id=? AND status="DRAFT"',[$this->access->user['id'],$id]);$this->repo->db->commit();$this->view->redirect('/inventory/issue-detail?id='.$id);}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}}
 public function reservations():void{$this->access->demand('inventory.reservation.view');$rows=$this->repo->all('SELECT r.*,b.code branch_code,w.code warehouse_code FROM inv_reservations r JOIN branches b ON b.id=r.branch_id JOIN inv_warehouses w ON w.id=r.warehouse_id WHERE r.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY r.id DESC',[$this->access->user['id'],$this->access->user['all_branches']]);$this->view->render('inventory-reservations',['title'=>'Reservasi Stok','rows'=>$rows,'branches'=>[],'warehouses'=>[],'items'=>[],'status'=>'']);}
